def compute_effective_rank(svals: torch.Tensor) -&gt; float:
  if svals.numel() == 0:
    return 0.0
  power = svals.pow(2)
  total = power.sum()
  if total &lt;= 0:
    return 0.0
  probs = power / total
  entropy = -(probs * torch.log(probs + 1e-12)).sum()
  return torch.exp(entropy).item()


